// ── source: vcx/tests/stdlib_xap_pep_test.v ──
// Behavioral TDD for the bundled cx-xap PEP (cx-private #7,
// spec/03-approved/xap/xap.md). The PEP is the cascade's step 1 (§2.2):
// principals have inherent authority; an agent must hold a dial-issued delegation;
// an un-granted intent is denied (CXER4850) and appends NOTHING; why-allowed is
// computed from the store (revoke flips it). These assert BEHAVIOR, not names.

const guestbook_setup = "[?lib 'cx-xap' :as xap]
[\$xap:component guestbook
  {bind: \"/guestbook\"
   emits: ([do :sign [name :string]])
   view: [?fn (\$gs) [panel [list]]]
   working-panel: :none}]
"

// An agent intent with NO dial is DENIED (CXER4850) — no covering delegation.
fn test_agent_denied_without_dial() {
	prog := guestbook_setup +
		"[?let [= \$rt [\$xap:run {tenant: \"demo\" components: (guestbook)}]]
  [\$xap:emit \$rt [do :sign [name \"Lin\"]] {actor: \"agent:greeter-1\"}]]"
	out := code.eval_code('', prog, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out.contains('CXER4850'), 'agent emit without a dial must be denied (CXER4850), got: ${out}'
	assert !out.contains('Lin'), 'a denied intent must append nothing, got: ${out}'
}

// The denied agent intent left the journal/state EMPTY (append nothing on deny).
fn test_deny_appends_nothing() {
	prog := guestbook_setup +
		"[?let [= \$rt [\$xap:run {tenant: \"demo\" components: (guestbook)}]]
[= \$x [\$xap:emit \$rt [do :sign [name \"Lin\"]] {actor: \"agent:greeter-1\"}]]
  [\$xap:state \$rt \"/guestbook\"]]"
	out := code.eval_code('', prog, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert !out.contains('Lin'), 'denied emit must not be in state, got: ${out}'
}

// After the dial issues the covering delegation, the SAME agent intent is admitted
// and folds into state.
fn test_agent_admitted_after_dial() {
	prog := guestbook_setup +
		"[?let [= \$rt [\$xap:run {tenant: \"demo\" components: (guestbook)}]]
[= \$d [\$xap:dial \$rt [from id=\"principal:dana\"] [to id=\"agent:greeter-1\"] [scope :guestbook] [setting :semi-auto]]]
[= \$b [\$xap:emit \$rt [do :sign [name \"Lin\"]] {actor: \"agent:greeter-1\"}]]
  [\$xap:state \$rt \"/guestbook\"]]"
	out := code.eval_code('', prog, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out.contains('Lin'), 'agent emit AFTER the dial must be admitted + folded, got: ${out}'
	assert !out.contains('CXER4850'), 'admitted emit must not be denied, got: ${out}'
}

// A principal actor has inherent authority — admitted with no dial at all.
fn test_principal_inherent_authority() {
	prog := guestbook_setup +
		"[?let [= \$rt [\$xap:run {tenant: \"demo\" components: (guestbook)}]]
[= \$h [\$xap:emit \$rt [do :sign [name \"Ada\"]] {actor: \"principal:dana\"}]]
  [\$xap:state \$rt \"/guestbook\"]]"
	out := code.eval_code('', prog, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out.contains('Ada'), 'principal emit must be admitted (inherent authority), got: ${out}'
	assert !out.contains('CXER4850'), 'principal must not be denied, got: ${out}'
}

// why-allowed is COMPUTED: true after the dial, then REVOKE flips it to false.
fn test_why_allowed_revoke_flips() {
	prog_allowed := guestbook_setup +
		"[?let [= \$rt [\$xap:run {tenant: \"demo\" components: (guestbook)}]]
[= \$d [\$xap:dial \$rt [from id=\"principal:dana\"] [to id=\"agent:greeter-1\"] [scope :guestbook] [setting :semi-auto]]]
  [\$xap:why-allowed \$rt [do :sign [name \"Lin\"]] {actor: \"agent:greeter-1\"}]]"
	out_allowed := code.eval_code('', prog_allowed, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out_allowed.contains("allowed='true'"), 'after dial, why-allowed must be true, got: ${out_allowed}'

	prog_revoked := guestbook_setup +
		"[?let [= \$rt [\$xap:run {tenant: \"demo\" components: (guestbook)}]]
[= \$d [\$xap:dial \$rt [from id=\"principal:dana\"] [to id=\"agent:greeter-1\"] [scope :guestbook] [setting :semi-auto]]]
[= \$r [\$xap:revoke \$rt \"d-dial-guestbook\"]]
  [\$xap:why-allowed \$rt [do :sign [name \"Lin\"]] {actor: \"agent:greeter-1\"}]]"
	out_revoked := code.eval_code('', prog_revoked, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out_revoked.contains("allowed='false'"), 'after revoke, why-allowed must flip to false, got: ${out_revoked}'
}

// After revoke, the agent's emit is again DENIED (the gate re-closes).
fn test_emit_denied_after_revoke() {
	prog := guestbook_setup +
		"[?let [= \$rt [\$xap:run {tenant: \"demo\" components: (guestbook)}]]
[= \$d [\$xap:dial \$rt [from id=\"principal:dana\"] [to id=\"agent:greeter-1\"] [scope :guestbook] [setting :semi-auto]]]
[= \$r [\$xap:revoke \$rt \"d-dial-guestbook\"]]
  [\$xap:emit \$rt [do :sign [name \"Lin\"]] {actor: \"agent:greeter-1\"}]]"
	out := code.eval_code('', prog, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out.contains('CXER4850'), 'after revoke the agent emit must be denied again, got: ${out}'
}

// ── source: vcx/tests/stdlib_xsp_test.v ──
// TDD for cx-stdlib/xsp (spec/03-approved/xap/xsp.md; issue #31). XSP is the XAP
// Stream Protocol frame codec: a self-describing, self-delimiting frame whose
// payload dogfoods CX `data-bin`. The whole codec is PURE (no capability grant),
// so these run under eval_code's deny-all caps.

fn xsp_eval(prog string) string {
	out := code.eval_code('', prog, 'text') or {
		assert false, 'eval failed: ${err}'
		return ''
	}
	return out
}

// Round-trip: encode a frame then decode it; the frame metadata and the
// data-bin payload value all survive unchanged.
fn test_xsp_roundtrip_binary_payload() {
	prog := "[?lib 'cx-stdlib/xsp' :as xsp]
[\$xsp:decode [\$xsp:encode [frame type=event stream=7 principal=\"did:key:z6MkABC\"
  [payload [fix lat=37.5 lon=-122.3]]]]]"
	out := xsp_eval(prog)
	assert out.contains('type=event'), 'type lost: ${out}'
	assert out.contains("stream='7'"), 'stream-id lost: ${out}'
	assert out.contains('did:key:z6MkABC'), 'principal lost: ${out}'
	assert out.contains('lat='), 'payload value lost: ${out}'
	assert out.contains('37.5'), 'payload lat value lost: ${out}'
	assert out.contains('-122.3'), 'payload lon value lost: ${out}'
	assert out.contains("binary='true'"), 'binary flag lost: ${out}'
}

// An anonymous frame (no principal) round-trips with an empty principal.
fn test_xsp_anonymous_frame() {
	prog := "[?lib 'cx-stdlib/xsp' :as xsp]
[\$xsp:decode [\$xsp:encode [frame type=request [payload [do :ping]]]]]"
	out := xsp_eval(prog)
	assert out.contains('type=request'), 'type lost: ${out}'
	assert out.contains("stream='0'"), 'default stream should be 0: ${out}'
	// the [do :ping] intent survives as the payload value
	assert out.contains('do') && out.contains('ping'), 'intent payload lost: ${out}'
}

// A text payload (binary=false) carries a UTF-8 string, not data-bin.
fn test_xsp_text_payload() {
	prog := "[?lib 'cx-stdlib/xsp' :as xsp]
[\$xsp:decode [\$xsp:encode [frame type=event binary=false [payload \"hello xsp\"]]]]"
	out := xsp_eval(prog)
	assert out.contains("binary='false'"), 'binary flag should be false: ${out}'
	assert out.contains('hello xsp'), 'text payload lost: ${out}'
}

// end-of-stream flag round-trips.
fn test_xsp_eos_flag() {
	prog := "[?lib 'cx-stdlib/xsp' :as xsp]
[\$xsp:decode [\$xsp:encode [frame type=reply eos=true [payload [ok]]]]]"
	out := xsp_eval(prog)
	assert out.contains("eos='true'"), 'eos flag lost: ${out}'
}

// decode-all splits a buffer of two concatenated frames into a sequence.
fn test_xsp_decode_all_splits_two() {
	prog := "[?lib 'cx-stdlib/xsp' :as xsp]
[?lib 'cx-stdlib/bytes' :as b]
[?let [= \$f1 [\$xsp:encode [frame type=event stream=1 [payload [a x=1]]]]]
[= \$f2 [\$xsp:encode [frame type=event stream=2 [payload [b y=2]]]]]
  [\$xsp:decode-all [\$b:concat (\$f1, \$f2)]]]"
	out := xsp_eval(prog)
	assert out.contains("stream='1'"), 'first frame lost: ${out}'
	assert out.contains("stream='2'"), 'second frame lost: ${out}'
	assert out.contains('x=1') && out.contains('y=2'), 'payloads lost: ${out}'
}

// An unknown version byte is rejected (a failure-channel err value).
fn test_xsp_bad_version_errs() {
	// 18 zero bytes: version byte 0x00 is not XSP/1.
	prog := "[?lib 'cx-stdlib/xsp' :as xsp]
[?lib 'cx-stdlib/bytes' :as b]
[\$xsp:decode [\$b:from-hex \"000000000000000000000000000000000000\"]]"
	out := xsp_eval(prog)
	assert out.contains('CXER5000'), 'expected version err, got: ${out}'
}

// A truncated buffer (header claims more than is present) is rejected.
fn test_xsp_truncated_errs() {
	prog := "[?lib 'cx-stdlib/xsp' :as xsp]
[?lib 'cx-stdlib/bytes' :as b]
[\$xsp:decode [\$b:from-hex \"0102\"]]"
	out := xsp_eval(prog)
	assert out.contains('CXER5001'), 'expected truncated err, got: ${out}'
}

// §5.2 (#560): the negotiated-only `credit` frame (type 8) round-trips —
// the payload is a data-bin integer grant.
fn test_xsp_credit_frame_roundtrip() {
	prog := "[?lib 'cx-stdlib/xsp' :as xsp]
[\$xsp:decode [\$xsp:encode [frame type=credit stream=42 [payload 7]]]]"
	out := xsp_eval(prog)
	assert out.contains('type=credit'), 'credit type lost: ${out}'
	assert out.contains("stream='42'") || out.contains('stream=42'), 'stream lost: ${out}'
	assert out.contains('7'), 'grant payload lost: ${out}'
}

// ── source: vcx/tests/vc_roundtrip_test.v ──
// vc_roundtrip_test.v — VCs must verify OFFLINE after any emit→parse
// round-trip (file, store, wire): the market/entitlement design rests on
// committed credentials verifying without their issuing process. A parsed
// credential carries barewords as TextNodes (not ScalarNode strings), which
// vc_child_text rejected — every round-tripped VC verified as "malformed"
// while the identical claim verified fresh. M4's fixtures only covered fresh
// in-memory VCs, so the gap survived until the first committed VC
// (xap-store-console's gratis free-tier entitlements). Black-box against the
// real binary, like module_pkg_loader_test.v.

fn vcrt_cx_binary() string {
	return testenv.cx_bin()
}

fn vcrt_run(prog string) string {
	tmp := os.join_path(os.temp_dir(), 'cx-vcrt-${os.getpid()}.cx')
	os.write_file(tmp, prog) or { panic('write: ${err}') }
	defer {
		os.rm(tmp) or {}
	}
	res := os.execute('${vcrt_cx_binary()} --allow-random ${tmp}')
	if res.exit_code != 0 {
		panic('cx failed (${res.exit_code}): ${res.output}')
	}
	return res.output
}

const vcrt_perpetual = "
[?lib 'cx-xap' :as xap]
[?lib 'cx-stdlib/crypto' :as crypto]
[?lib 'cx-stdlib/did' :as did]
[?let [= \$kp [\$crypto:ed25519-keypair]]
 [= \$pub [\$did:key-create \$kp@public]]
 [= \$lic [\$xap:license-issue \$pub \$kp@private 'principal:alice' {package: 'pkg-a' versions: '0.x' kind: 'perpetual'}]]
 [= \$rt [\$cx:parse [\$cx:emit \$lic]]]
 [= \$lic2 [\$first [?for [in \$x \$rt//vc] [yield \$x]]]]
 [= \$v1 [\$xap:license-verify \$lic 'pkg-a' '0.1.0' {now: '2026-07-07T00:00:00Z'}]]
 [= \$v2 [\$xap:license-verify \$lic2 'pkg-a' '0.1.0' {now: '2026-07-07T00:00:00Z'}]]
 [\$concat 'fresh=' \$v1@status ' reparsed=' \$v2@status]]"

const vcrt_subscription = "
[?lib 'cx-xap' :as xap]
[?lib 'cx-stdlib/crypto' :as crypto]
[?lib 'cx-stdlib/did' :as did]
[?let [= \$kp [\$crypto:ed25519-keypair]]
 [= \$pub [\$did:key-create \$kp@public]]
 [= \$lic [\$xap:license-issue \$pub \$kp@private 'principal:alice' {package: 'pkg-a' versions: '0.x' expires: '2027-01-01T00:00:00Z' grace-until: '2027-02-01T00:00:00Z'}]]
 [= \$rt [\$cx:parse [\$cx:emit \$lic]]]
 [= \$lic2 [\$first [?for [in \$x \$rt//vc] [yield \$x]]]]
 [= \$v2 [\$xap:license-verify \$lic2 'pkg-a' '0.1.0' {now: '2026-07-07T00:00:00Z'}]]
 [\$concat 'reparsed=' \$v2@status]]"

fn test_vc_verifies_after_emit_parse_roundtrip() {
	out := vcrt_run(vcrt_perpetual)
	assert out.contains('fresh=ok'), 'fresh VC must verify: ${out}'
	assert out.contains('reparsed=ok'), 'ROUND-TRIPPED VC must verify (offline portability): ${out}'
}

fn test_vc_with_expiry_verifies_after_roundtrip() {
	// dates re-parse as TYPED scalars, not strings — extraction must
	// stringify those too (expires drives the grace-window logic).
	out := vcrt_run(vcrt_subscription)
	assert out.contains('reparsed=ok'), 'round-tripped subscription VC must verify: ${out}'
}

// ── stream 6 W3 (#678 / #713 item 4): authority-store durability ──
// The TRUE restart evidence: trust state issued in one evaluated program
// (fresh env #1) survives into a SECOND evaluated program (fresh env #2 —
// new_env resets the in-process authz registry, so only the file:// journal
// carries state across) — the persisted-grant-then-reopen path (R6).
fn test_authz_durability_survives_env_restart() {
	code.caps_set_all()
	dir := os.join_path(os.temp_dir(), 'cx_authz_dur_${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { assert false, 'mkdir ${dir}: ${err}' }
	defer {
		os.rmdir_all(dir) or {}
	}
	url := 'file://${dir}'
	prog1 := "[?lib 'cx-stdlib/authz']
[?lib 'cx-stdlib/journal' as=journal]
[?let [= \$j [\$journal:open \"${url}\" \"acme\"]]
  [= \$az [\$authz:store {tenant: 'acme', journal: \$j}]]
  [= \$d [\$authz:delegate \$az
    [delegation d-restart [tenant acme] [from [principal dana]] [to [agent ops-1]]
      [capabilities [refund]] [assurance :t1] [signature s]]]]
  [= \$c [\$authz:close \$az]]
  [\$journal:close \$j]]"
	out1 := code.eval_code('', prog1, 'text') or {
		assert false, 'program 1 (issue) failed: ${err}'
		return
	}
	assert !out1.contains('cx-err:'), 'program 1 must issue cleanly, got: ${out1}'
	// Program 2 — a FRESH env: the authz registry is reset at new_env; the
	// grant must come back through journal replay alone.
	prog2 := "[?lib 'cx-stdlib/authz']
[?lib 'cx-stdlib/journal' as=journal]
[?let [= \$j [\$journal:open \"${url}\" \"acme\"]]
  [= \$az [\$authz:store {tenant: 'acme', journal: \$j}]]
  [\$authz:check \$az [authz-request [actor [agent ops-1]] [capability refund] [tenant acme]]]]"
	out2 := code.eval_code('', prog2, 'text') or {
		assert false, 'program 2 (reopen + check) failed: ${err}'
		return
	}
	assert out2.contains('permit'), 'the reopened store must PERMIT from replayed trust state (R6), got: ${out2}'
	assert out2.contains('d-restart'), 'the permit must cite the replayed delegation, got: ${out2}'
	// Program 3 — revoke in a fresh env, then a fourth env must deny.
	prog3 := "[?lib 'cx-stdlib/authz']
[?lib 'cx-stdlib/journal' as=journal]
[?let [= \$j [\$journal:open \"${url}\" \"acme\"]]
  [= \$az [\$authz:store {tenant: 'acme', journal: \$j}]]
  [\$authz:revoke \$az 'd-restart']]"
	out3 := code.eval_code('', prog3, 'text') or {
		assert false, 'program 3 (revoke) failed: ${err}'
		return
	}
	assert !out3.contains('cx-err:'), 'program 3 must revoke cleanly, got: ${out3}'
	out4 := code.eval_code('', prog2, 'text') or {
		assert false, 'program 4 (post-revoke check) failed: ${err}'
		return
	}
	assert out4.contains('deny'), 'post-revoke restart must DENY (no resurrection), got: ${out4}'
}

// ── #781 (batch #796): temp-dir must never hand back a leftover ──
// POST-APPLY umbrella addition — not in scripts/consolidation/stdlib.files;
// reconcile it into the manifest inputs before any future regeneration.
//
// [$io:temp-dir P] named the directory <temp>/<P><pid>-<counter> and
// mkdir_all'd it. That is unique within ONE process, but pids recycle and
// nothing cleans the system temp dir, so a later generation whose pid
// matched a leftover directory reused it — stale contents and all (seen as
// io-058/io-083 false-reds in a full gate). The repro pre-takes the names
// the next tokens would draw, each carrying a marker file: before the fix
// temp-dir hands one of them back (marker included); after it, mkdir
// refuses every taken name and the search walks on to a fresh, empty one.
fn test_temp_dir_never_reuses_a_leftover_directory() {
	code.caps_set_all()
	prog := "[?lib 'cx-stdlib/io']\n[\$io:temp-dir 'cxc781']"
	raw1 := code.eval_code('', prog, 'text') or {
		assert false, 'first temp-dir failed: ${err}'
		return
	}
	d1 := raw1.trim_space().trim("'\"")
	assert os.is_dir(d1), 'first temp-dir must name a real directory, got: ${raw1}'
	defer {
		os.rmdir_all(d1) or {}
	}
	// The token tail is '<pid>-<counter>': pre-take the next three names.
	dash := d1.last_index('-') or {
		assert false, 'unexpected temp-dir name shape: ${d1}'
		return
	}
	stem := d1[..dash + 1]
	n := d1[dash + 1..].int()
	mut taken := []string{}
	for k in 1 .. 4 {
		leftover := '${stem}${n + k}'
		os.mkdir_all(leftover) or { continue }
		os.write_file(os.join_path(leftover, 'stale'), 'from a prior generation') or {}
		taken << leftover
	}
	defer {
		for t in taken {
			os.rmdir_all(t) or {}
		}
	}
	assert taken.len == 3, 'the repro needs the next three names pre-taken, got ${taken.len}'
	raw2 := code.eval_code('', prog, 'text') or {
		assert false, 'second temp-dir failed: ${err}'
		return
	}
	d2 := raw2.trim_space().trim("'\"")
	defer {
		os.rmdir_all(d2) or {}
	}
	assert d2 !in taken, 'temp-dir handed back a LEFTOVER directory: ${d2}'
	assert os.is_dir(d2), 'temp-dir must create the directory it names: ${d2}'
	entries := os.ls(d2) or { []string{} }
	assert entries.len == 0, 'temp-dir must return an EMPTY directory, found: ${entries}'
}
